def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]

    last_me = my[-1]
    last_opp = opp[-1]
    prev_opp = opp[-2] if n >= 2 else last_opp

    total_c = sum(1 for a in opp if a == 'C')
    total_ratio = total_c / float(n)

    recent_len = min(12, n)
    recent = opp[n - recent_len:]
    recent_c = sum(1 for a in recent if a == 'C')
    recent_ratio = recent_c / float(recent_len)

    d_streak = 0
    for a in reversed(opp):
        if a == 'D':
            d_streak += 1
        else:
            break

    c_streak = 0
    for a in reversed(opp):
        if a == 'C':
            c_streak += 1
        else:
            break

    punished = 0
    forgiven = 0
    for i in range(1, n):
        if my[i - 1] == 'D':
            if opp[i] == 'D':
                punished += 1
            else:
                forgiven += 1

    evidence = punished + forgiven
    if evidence >= 2:
        punish_rate = punished / float(evidence)
    else:
        punish_rate = 1.0

    unpunishing = evidence >= 2 and punish_rate <= 0.4 and total_ratio > 0.55
    soft = punished == 0 and forgiven >= 1 and total_ratio > 0.55

    period_ratio = 0.0
    predicted = last_opp
    periodic = False
    if n >= 15:
        match5 = 0
        total5 = n - 5
        for i in range(5, n):
            if opp[i] == opp[i - 5]:
                match5 += 1
        period_ratio = match5 / float(total5) if total5 else 0.0
        periodic = period_ratio >= 0.78 and (n - total_c) >= 1
        if periodic:
            predicted = opp[n - 5]

    if periodic:
        if predicted == 'D':
            if unpunishing or soft or recent_ratio <= 0.62 or total_ratio <= 0.70:
                return 'D'
        else:
            if unpunishing or soft:
                return 'D' if rng.random() < 0.7 else 'C'

    if n >= 6:
        last6 = opp[-6:]
        if all(a == 'D' for a in last6):
            if unpunishing and recent_ratio > 0.35 and rng.random() < 0.15:
                return 'C'
            return 'D'

    hostile = (total_ratio <= 0.35) or (recent_ratio <= 0.25 and n >= 10) or (d_streak >= 5 and total_ratio <= 0.78)

    if last_opp == 'D':
        if unpunishing and d_streak <= 4 and recent_ratio > 0.35:
            return 'D'
        if soft and d_streak <= 2 and recent_ratio > 0.45:
            return 'D'
        if hostile:
            return 'D'

        if d_streak <= 3 and total_ratio > 0.75 and recent_ratio > 0.55:
            return 'C'
        if d_streak == 4 and total_ratio > 0.68 and recent_ratio > 0.5:
            return 'C'
        if d_streak == 1 and total_ratio > 0.75:
            return 'C'
        if last_me == 'D' and total_ratio > 0.55 and punished <= 3:
            return 'C'

        return 'D'

    if last_opp == 'C':
        if last_me == 'D':
            if unpunishing:
                return 'D' if rng.random() < 0.85 else 'C'
            if soft:
                return 'D' if rng.random() < 0.7 else 'C'
            return 'C'

        if unpunishing:
            return 'D' if rng.random() < 0.8 else 'C'
        if soft:
            return 'D' if rng.random() < 0.6 else 'C'

        if total_ratio < 0.45:
            return 'D' if rng.random() < 0.75 else 'C'

        if punished == 0 or (evidence >= 2 and punish_rate <= 0.5) or punished <= forgiven:
            if total_ratio >= 0.82 and recent_ratio >= 0.7 and c_streak >= 8:
                if rng.random() < 0.05:
                    return 'D'
            if prev_opp == 'D' and c_streak <= 5 and total_ratio > 0.55 and recent_ratio > 0.35:
                if rng.random() < 0.09:
                    return 'D'
            if total_c == n and n >= 8:
                if rng.random() < 0.04:
                    return 'D'

    return 'C'
